import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';

const Appointments = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
    const [appointments, setAppointments] = useState([]);
    const [loading, setLoading] = useState(true);

    // 1. Fetch REAL appointments from the database when page loads
    useEffect(() => {
        const fetchAppointments = async () => {
            try {
                const token = localStorage.getItem('token');
                const response = await axios.get('http://localhost:5000/api/appointments', {
                    headers: { Authorization: `Bearer ${token}` }
                });
                // This sets the list based on what is in your database
                setAppointments(response.data.data);
            } catch (error) {
                console.error("Failed to load appointments", error);
            } finally {
                setLoading(false);
            }
        };
        fetchAppointments();
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/login');
    };

    const isActive = (path) => location.pathname === path;

    return (
        <div className="appointments-page">
            <nav className="appointments-navbar">
                <div className="nav-logo">BeautyBook</div>
                <div className="nav-links-desktop">
                    <span className={`nav-item ${isActive('/services') ? 'active' : ''}`} onClick={() => navigate('/services')}>🌸 Beauty treatments</span>
                    <span className={`nav-item ${isActive('/appointments') ? 'active' : ''}`}>📅 Appointment</span>
                    <span className="nav-icon">🔔</span>
                    <span className="nav-icon" onClick={handleLogout} style={{cursor: 'pointer'}}>⚙️</span>
                </div>
                <div className="hamburger-icon" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>☰</div>
            </nav>

            <div className={`mobile-sidebar ${isMobileMenuOpen ? 'open' : ''}`}>
                <div className="sidebar-content">
                    <div className="sidebar-title">BeautyBook</div>
                    <div className="sidebar-item" onClick={() => { setIsMobileMenuOpen(false); navigate('/services'); }}>🌸 Beauty treatments</div>
                    <div className="sidebar-item active">📅 Appointment</div>
                    <div className="sidebar-icon-row"><span>🔔</span><span onClick={() => { setIsMobileMenuOpen(false); handleLogout(); }}>⚙️</span></div>
                </div>
            </div>

            <div className="appointments-content">
                <div className="filter-pills">
                    <button className="pill active">All appointment</button>
                    <button className="pill">Appointment confirmed</button>
                    <button className="pill">Discount offer</button>
                </div>

                {/* 2. Wait for data to load from database */}
                {loading ? (
                    <div className="loading">Loading your appointments...</div>
                ) : (
                    <div className="appointments-list">
                        {/* 3. If the database returns an empty array, show this message */}
                        {appointments.length === 0 ? (
                            <div style={{ 
                                color: '#fff', 
                                textAlign: 'center', 
                                fontSize: '20px', 
                                marginTop: '50px',
                                fontFamily: "'Inter', sans-serif"
                            }}>
                                🗓️ You haven't booked any appointments yet.
                                <br />
                                <span style={{ fontSize: '16px', opacity: 0.8 }}>
                                    Go to <strong>Beauty treatments</strong> to book your first one!
                                </span>
                            </div>
                        ) : (
                            /* 4. If there are appointments, display them */
                            appointments.map((app) => (
                                <div key={app._id} className="appointment-card">
                                    <div className="card-image">
                                        {/* You might want to save the image URL in the database later */}
                                        <img src="/Soin%20visage.jpeg" alt={app.title} />
                                    </div>
                                    <div className="card-details">
                                        <h3 className="card-title">{app.title}</h3>
                                        <div className="card-meta">
                                            <span>prix : {app.price}</span>
                                            <span>Duration : {app.duration}</span>
                                            <span>Date : {app.date}</span>
                                            <span>Time : {app.time}</span>
                                        </div>
                                    </div>
                                    <div className="card-actions">
                                        <button className="cancel-btn">Cancel Appointment if you want</button>
                                        <div className="status-badge">
                                            {app.status}
                                            <span className={`status-dot ${app.status === 'Pending Confirmation' ? 'yellow' : app.status === 'Confirmed' ? 'green' : app.status === 'Completed' ? 'blue' : 'red'}`}></span>
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

export default Appointments;
